class Solution {
public:
    vector<int> maxSubsequence(vector<int>& nums, int k) {
        int n = nums.size();
        vector<pair<int,int>> vec;
        vec.reserve(n);
        for (int i = 0; i < n; ++i) {
            vec.emplace_back(nums[i], i);
        }
        sort(vec.begin(), vec.end(), [](const auto& a, const auto& b){
            return a.first > b.first; // descending by value
        });
        vector<int> idx;
        idx.reserve(k);
        for (int i = 0; i < k; ++i) {
            idx.push_back(vec[i].second);
        }
        sort(idx.begin(), idx.end()); // ascending by original index
        vector<int> res;
        res.reserve(k);
        for (int id : idx) {
            res.push_back(nums[id]);
        }
        return res;
    }
};

