import java.util.*;

class Solution {
    public int[] maxSubsequence(int[] nums, int k) {
        int n = nums.length;
        // Pair each value with its original index
        List<int[]> pairs = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            pairs.add(new int[]{nums[i], i});
        }

        // Sort descending by value
        pairs.sort((a, b) -> Integer.compare(b[0], a[0]));

        // Collect indices of the first k elements (largest values)
        int[] idx = new int[k];
        for (int i = 0; i < k; ++i) {
            idx[i] = pairs.get(i)[1];
        }

        // Sort indices to restore original order
        Arrays.sort(idx);

        // Build result subsequence using the sorted indices
        int[] res = new int[k];
        for (int i = 0; i < k; ++i) {
            res[i] = nums[idx[i]];
        }
        return res;
    }
}

