/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */
var maxSubsequence = function(nums, k) {
    const n = nums.length;
    // store value and original index
    const vec = [];
    for (let i = 0; i < n; ++i) {
        vec.push([nums[i], i]); // [value, index]
    }
    // sort descending by value
    vec.sort((a, b) => b[0] - a[0]);

    // take first k indices
    const idx = [];
    for (let i = 0; i < k; ++i) {
        idx.push(vec[i][1]);
    }
    // sort indices to restore original order
    idx.sort((a, b) => a - b);

    // build result subsequence
    const res = [];
    for (const id of idx) {
        res.push(nums[id]);
    }
    return res;
};
